#pragma once
#define ADAPTER_PANEL_HTML "<!doctype html><html lang=ru><meta charset=utf-8><meta name=viewport content=\"width=device-width,initial-scale=1\"><title>BC250 Waveshare</title><link rel=icon href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='6' fill='%23007aff'/%3E%3C/svg%3E\"><style>body{background:#f5f5f7;color:#1d1d1f;font:15px system-ui;max-width:700px;margin:24px auto;padding:0 16px}section{background:white;border:1px solid #ddd;border-radius:10px;padding:16px;margin:12px 0}input,button{font:inherit;padding:8px;max-width:100%;box-sizing:border-box}button{background:#007aff;color:white;border:0;border-radius:6px}dl{display:grid;grid-template-columns:1fr 1fr;gap:12px}dd{margin:0}small{color:#666}</style><h1>BC-250 / Waveshare</h1><section><label>Токен доступа <input id=t type=password autocomplete=off maxlength=64></label><button id=b>Прочитать</button><p id=n>Только чтение.</p></section><section><dl><dt>Геймпад</dt><dd id=bt>нет данных</dd><dt>ОС отвечает</dt><dd id=os>неизвестно</dd><dt>CPU, °C</dt><dd id=cpu>нет данных</dd><dt>GPU, °C</dt><dd id=gpu>нет данных</dd><dt>GPU, W</dt><dd id=w>нет данных</dd><dt>fan1, RPM</dt><dd id=f1>нет данных</dd><dt>fan2, RPM</dt><dd id=f2>нет данных</dd><dt>UART RX</dt><dd id=u>нет данных</dd></dl><small>Linux hwmon. Нет данных ≠ ноль.</small></section><script>const E=x=>document.getElementById(x);E('b').onclick=async()=>{E('b').disabled=true;try{const r=await fetch('/api/status',{headers:{Authorization:'Bearer '+E('t').value},cache:'no-store'});if(!r.ok)throw 0;const d=await r.json();if(typeof d.bt_connected!=='boolean'||!['on','unknown'].includes(d.power)||typeof d.uart?.enabled!=='boolean')throw 0;const m=d.metrics||{};E('bt').textContent=d.bt_connected?'подключён':'не подключён';E('os').textContent=d.power==='on'?'да':'неизвестно';for(const [id,key,scale] of [['cpu','cpu_temp_milli_c',1000],['gpu','gpu_temp_milli_c',1000],['w','gpu_power_milli_w',1000],['f1','fan1_rpm',1],['f2','fan2_rpm',1]])E(id).textContent=typeof m[key]==='number'&&Number.isFinite(m[key])?(m[key]/scale).toFixed(2):'нет данных';E('u').textContent=d.uart?.enabled?'приём':'выключен';E('n').textContent='Ответ получен.';}catch{for(const id of ['bt','os','cpu','gpu','w','f1','f2','u'])E(id).textContent='нет данных';E('n').textContent='Нет ответа.';}finally{E('b').disabled=false;}};</script></html>"
